import{_ as o,o as n,c as s,a2 as t}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Sovereign Tasks Connector","description":"","frontmatter":{"epic":4,"title":"Sovereign Tasks Connector","status":"📋 Planned","scope":"mobile","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/mobile/sovereign-tasks-connector.md"},"headers":[],"relativePath":"sovereign-edge/epics/mobile/sovereign-tasks-connector.md","filePath":"sovereign-edge/epics/mobile/sovereign-tasks-connector.md"}'),r={name:"sovereign-edge/epics/mobile/sovereign-tasks-connector.md"};function a(i,e,c,l,d,h){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="epic-sovereign-tasks-connector" tabindex="-1">Epic: Sovereign Tasks Connector <a class="header-anchor" href="#epic-sovereign-tasks-connector" aria-label="Permalink to &quot;Epic: Sovereign Tasks Connector&quot;">​</a></h1><blockquote><p>The default Phase 2 connector for scenario 3 — creating a task on a user&#39;s own self-hosted <code>sovereign</code> instance, via a direct API call.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Second consumer of the <a href="./connector-framework.html">Connector Framework</a>, and the one deliberate point of optional overlap with the wider <code>sovereignfs</code> ecosystem — entirely opt-in, and the app has zero dependency on <code>sovereign</code> existing. Per research 0001&#39;s decision, this calls the user&#39;s self-hosted <code>sovereign</code> instance&#39;s task API <strong>directly over HTTPS</strong>, whether or not a native Sovereign app happens to be installed on the same device — there is no on-device app-to-app IPC involved.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-4-1-—-sovereign-tasks-connector" tabindex="-1">📋 4.1 — Sovereign Tasks connector <a class="header-anchor" href="#📋-4-1-—-sovereign-tasks-connector" aria-label="Permalink to &quot;📋 4.1 — Sovereign Tasks connector&quot;">​</a></h4><p><strong>Goal:</strong> Let the model create a task in a user&#39;s own <code>sovereign</code> instance on request.</p><p><strong>Deliverables:</strong></p><ul><li>Connector manifest (per epic 2&#39;s schema) for a <code>tasks.create</code> tool, targeting <code>sovereign</code>&#39;s Tasks plugin API.</li><li>Direct integration, not delegation: the connector holds its own stored, permissioned API token and writes the task itself, rather than opening a Sovereign app UI for the user to confirm in.</li><li>Permission-gated per the Connector Framework — separate grant from the Search connector.</li></ul><p><strong>Dependencies:</strong> Connector Framework epic (2.1–2.4).</p><p><strong>Review checklist:</strong></p><ul><li>Creating a task via chat results in a real task appearing in the user&#39;s <code>sovereign</code> instance&#39;s Tasks plugin.</li><li>Revoking this connector&#39;s permission does not affect the Search connector&#39;s permission or vice versa.</li></ul><hr><h4 id="📋-4-2-—-instance-url-and-api-token-setup-flow" tabindex="-1">📋 4.2 — Instance URL and API token setup flow <a class="header-anchor" href="#📋-4-2-—-instance-url-and-api-token-setup-flow" aria-label="Permalink to &quot;📋 4.2 — Instance URL and API token setup flow&quot;">​</a></h4><p><strong>Goal:</strong> A one-time setup flow for pointing this connector at the user&#39;s own instance.</p><p><strong>Deliverables:</strong></p><ul><li>Settings flow: paste instance URL, generate/paste an API token (generated in Sovereign&#39;s own settings — this task does not include building that token-generation UI inside <code>sovereign</code> itself, only consuming it here).</li><li>Clear error states for an unreachable instance, invalid token, or missing Tasks plugin.</li></ul><p><strong>Dependencies:</strong> Task 4.1.</p><p><strong>Review checklist:</strong></p><ul><li>An invalid token or unreachable instance produces a clear, actionable error rather than a silent failure.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./connector-framework.html">Connector Framework</a></li></ul><h2 id="cross-references" tabindex="-1">Cross-references <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-references&quot;">​</a></h2><ul><li>Depends on <code>sovereign</code>&#39;s own Tasks plugin API (<code>sovereign-tasks</code>) and whatever API-token mechanism <code>sovereign</code> exposes for external clients — see <code>sovereign</code>&#39;s own docs for that surface; this repo does not own or duplicate it.</li></ul>',24)])])}const u=o(r,[["render",a]]);export{g as __pageData,u as default};
